actions.script:
const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
guided.discard(guided.screenContext(rootId, path, page).target, {rootId: fileRootId, path: filePath})
ec.message.addMessage(ec.l10n.localize("The disk's text is back; the other staged files stay"), 'info')

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
guided.discard(guided.screenContext(rootId, path, page).target)
ec.message.addMessage(ec.l10n.localize('The unsaved changes are discarded'), 'info')

const found = ec.service.sync().name('org.moqui.devaide.ArtifactServices.search#Artifacts')
    .parameters({text: String(term || ''), kinds: 'service', limit: 20}).call() || {}
const options = (found.artifacts || []).map((row) => row.name || String(row.id || '').replace(/^service:/, ''))
    .map((name) => ({value: name, label: name}))
const asked = String(term || '')
ec.message.clearErrors()
ec.web.sendJsonResponse(asked && !options.some((option) => option.value === asked) && asked.indexOf('#') > 0
    ? [{value: asked, label: asked}].concat(options) : options)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const screen = guided.screenContext(rootId, path, page)
const raw = ec.web.secureRequestParameters
const built = screen.view ? guided.screenIntent(screen, node, String(intent || ''), {attrName, attrValue, fieldName, fieldTitle, widget,
    after, transitionName, serviceName, linkText, keyField, where, snippet, rawXml: raw.rawXml || rawXml, sectionKind, sectionName,
    sectionTitle, entityName}) : {refused: screen.refused || 'No screen'}
if (built.refused) ec.message.addError(built.refused)
else {
    guided.apply(screen.target, screen.edit, built.ops)
    if (built.node !== undefined && !ec.message.hasError()) node = built.node
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js') const screen = guided.screenContext(rootId, path, page) const ops = screen.ops.screen const pure = screen.ops.pure view = screen.view readError = screen.refused || '' tab = ['design', 'preview', 'text', 'points'].includes(tab) ? tab : 'design' extension = screen.extension baseFile = screen.baseFile || {} editFile = screen.editFile || {} const base = baseFile.outline || null hasEditTarget = !!screen.edit canEdit = !!(view && view.tier !== 'view' && screen.edit && !editFile.readOnly && base) screenName = view ? view.location.split('/').pop().replace(/\.xml$/, '') : '' headerText = view ? [view.location, view.urlPath || '', view.upstream ? 'upstream' : 'site'].filter((part) => part).join(' · ') : '' editsGo = !view ? '' : !screen.edit ? 'This screen is upstream and there is no site component to extend it in: create one on Home' : extension ? 'Extension mode: every edit goes to the site\'s ' + screen.edit.path : 'Edits go to ' + screen.edit.path readOnlyReason = view && screen.edit && editFile.readOnly ? editFile.readOnlyReason || '' : '' pendingText = guided.pendingText(screen.buffer) bufferExpired = !!screen.buffer.expired const left = guided.taken(screen.target) conflict = left.conflict || null problemRows = (left.problems || []).map((problem) => ({file: problem.file || '', line: problem.line || 0, severity: problem.severity || '', message: problem.message || ''})) const here = {rootId: rootId || null, path: path || null, page: page || null} const urlOf = (extra) => sri.buildUrl('../Design').addParameters(Object.assign({}, here, extra)).getUrlWithParams() tabItems = [['design', 'Design'], ['preview', 'Preview'], ['text', 'Text' + (screen.buffer.pending.count ? ' ' + screen.buffer.pending.count : '')], ['points', 'Extension points']].map(([name, title]) => ({title, url: urlOf({tab: name, node: node || null}), active: name === tab})) workspaceBase = baseFile.rootId ? '/qapps/dev/Workspace?rootId=' + encodeURIComponent(baseFile.rootId) + '&path=' + encodeURIComponent(baseFile.path) : ''
// the outline as the tree component's rows, each opening its element treeRows = base ? ops.outlineRows(base, (key) => urlOf({tab: 'design', node: key})) : [] // in extension mode the site's screen-extend has its own outline, its elements keyed e:<path> const extOutline = extension ? editFile.outline || null : null extensionTreeRows = extOutline ? ops.outlineRows(extOutline, (key) => urlOf({tab: 'design', node: 'e:' + key})) : [] ownNode = false selected = null if (extOutline && guided.isExtendKey(node)) { selected = pure.outlineAt(extOutline, guided.nodePath(String(node).slice(2))) ownNode = !!selected } if (!selected) selected = base ? pure.outlineAt(base, guided.nodePath(node)) : null if (!selected && base) selected = base const selectedKey = selected ? (ownNode ? 'e:' : '') + selected.path.join('.') : '' selectedText = selected ? (ownNode ? 'The site\'s ' : '') + selected.name + (ops.anchorName(selected) ? ' ' + ops.anchorName(selected) : '') + ' · line ' + selected.line : '' const workspaceEdit = editFile.rootId && !editFile.missing ? '/qapps/dev/Workspace?rootId=' + encodeURIComponent(editFile.rootId) + '&path=' + encodeURIComponent(editFile.path) : '' selectedUrl = selected ? (ownNode ? workspaceEdit : workspaceBase) : '' if (selectedUrl) selectedUrl += '&line=' + selected.line nodeValue = selectedKey const form = selected && base && !ownNode ? ops.formOf(base, selected.path) : null formKind = form ? form.name : '' formName = form ? pure.attrOf(form, 'name') || '' : '' formFieldOptions = form ? pure.children(form, ['field']).map((field) => ({name: pure.attrOf(field, 'name')})).filter((field) => field.name) : [] isTransition = !!(selected && !ownNode && selected.name === 'transition') isReplaceable = !!(selected && !ownNode && ['section', 'section-iterate', 'form-single', 'form-list'].includes(selected.name) && ops.anchorName(selected)) const nearest = selected && !ownNode && selected.path.length && !ops.anchorName(selected) ? ops.nearestAnchor(base, selected.path) : null anchorNote = extension && !ownNode && selected && selected.path.length ? (ops.anchorName(selected) && ops.ANCHORABLE.includes(selected.name) ? 'Inserts anchor at ' + ops.anchorName(selected) : nearest ? 'This element has no name: inserts go ' + nearest.where + ' ' + nearest.name + ', the nearest anchor' : 'Nothing near this element has a name to anchor at') : '' snippetOptions = ops.SNIPPETS.map((item) => ({key: item.key, label: item.label}))
// the properties of the selected element, from the schema digest: one row per attribute, its values when listed propertyRows = [] if (tab === 'design' && selected && (!extension || ownNode)) { const digest = guided.probe('org.moqui.dev.DevToolsServices.get#SchemaDigest', {rootElement: ownNode ? 'screen-extend' : base.name}).digest const spec = digest ? (digest.elements || []).find((element) => element.name === selected.name) : null const have = Object.fromEntries(selected.attrs || []) const listed = spec ? spec.attributes || [] : [] const names = listed.map((attr) => attr.name) propertyRows = listed.map((attr) => ({attrName: attr.name, attrValue: have[attr.name] == null ? '' : have[attr.name], valueOptions: (attr.values || []).map((value) => ({value})), choose: !!(attr.values || []).length && !attr.openValues, about: String(attr.doc || '').replace(/\s+/g, ' ').slice(0, 90) + (String(attr.doc || '').length > 90 ? '…' : '') + (attr.default != null ? ' (default ' + attr.default + ')' : ''), node: selectedKey})) .concat(Object.keys(have).filter((name) => !names.includes(name)).map((name) => ({attrName: name, attrValue: have[name], valueOptions: [], choose: false, about: 'Not in the schema', node: selectedKey}))) }
extensionPath = extension && screen.edit ? screen.edit.path : ''
// Preview: the screen's own terminal form, rendered from the staged buffer previewQuery = previewQuery != null ? previewQuery : (view ? view.query || '' : '') previewUrl = view && view.urlPath ? view.urlPath + '?' + (previewQuery ? previewQuery + '&' : '') + 'moquiPreview=' + encodeURIComponent('buffer:' + screen.buffer.bufferId) : '' // the terminal renders the screen in the apps tree: /qapps is the browser's app shell, which has no terminal form terminalPreviewUrl = previewUrl.replace(/^\/qapps\//, '/apps/') const givenNames = String(previewQuery || '').split('&').map((pair) => decodeURIComponent(pair.split('=')[0] || '')).filter((name) => name) requiredParameters = view ? (view.parameters || []).filter((parameter) => parameter.required && !givenNames.includes(parameter.name)) .map((parameter) => parameter.name).join(', ') : ''
// Text and the extension points targetText = (extension ? editFile.text : baseFile.text) || '' targetPath = screen.edit ? screen.edit.path : '' diffRows = screen.buffer.files.filter((file) => file.staged).map((file) => ({path: file.path, diff: file.diff || ''})) pointRows = base ? ops.extensionPoints(base).map((point) => ({kind: point.kind, name: point.name || '', line: point.line, nearest: point.nearest ? point.nearest.where + ' ' + point.nearest.name : '', url: urlOf({tab: 'design', node: point.path.join('.')})})) : []
